  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;claireur-De-Larm&#233;e-(R&#244;deur).html&quot; title=&quot;&#201;claireur de l&amp;#39;arm&#233;e&quot;&gt;&#201;claireur de l&#39;arm&#233;e&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fauconnier-(R&#244;deur).html&quot; title=&quot;Fauconnier&quot;&gt;Fauconnier&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flibustier-(R&#244;deur).html&quot; title=&quot;Flibustier&quot;&gt;Flibustier&lt;/a&gt; (PMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-(R&#244;deur).html&quot; title=&quot;Gardien&quot;&gt;Gardien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Des-Vagues-(R&#244;deur).html&quot; title=&quot;Gardien des vagues&quot;&gt;Gardien des vagues&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Poisson-(Race).html&quot; title=&quot;Les hommes-poissons&quot;&gt;Homme-poisson&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-(R&#244;deur).html&quot; title=&quot;Guide&quot;&gt;Guide&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-B&#234;tes-(R&#244;deur).html&quot; title=&quot;Ma&#238;tre des b&#234;tes&quot;&gt;Ma&#238;tre des b&#234;tes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Messager-Secret-(R&#244;deur).html&quot; title=&quot;Messager secret&quot;&gt;Messager secret&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ombre-Sauvage-(R&#244;deur).html&quot; title=&quot;Ombre sauvage&quot;&gt;Ombre sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pisteur-Divin-(R&#244;deur).html&quot; title=&quot;Pisteur divin&quot;&gt;Pisteur divin&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Infiltr&#233;-(R&#244;deur).html&quot; title=&quot;R&#244;deur infiltr&#233;&quot;&gt;R&#244;deur infiltr&#233;&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Libre-Du-Nirmathas-(R&#244;deur).html&quot; title=&quot;R&#244;deur libre des for&#234;ts&quot;&gt;R&#244;deur libre des for&#234;ts&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Spirituel-(R&#244;deur).html&quot; title=&quot;R&#244;deur spirituel&quot;&gt;R&#244;deur spirituel&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Urbain-(R&#244;deur).html&quot; title=&quot;R&#244;deur urbain&quot;&gt;R&#244;deur urbain&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-Des-Chevaux-(R&#244;deur).html&quot; title=&quot;Seigneur des chevaux&quot;&gt;Seigneur des chevaux&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sentinelle-(R&#244;deur).html&quot; title=&quot;Sentinelle&quot;&gt;Sentinelle&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tirailleur-(R&#244;deur).html&quot; title=&quot;Tirailleur&quot;&gt;Tirailleur&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Transporteur-(R&#244;deur).html&quot; title=&quot;Transporteur&quot;&gt;Transporteur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trappeur-(R&#244;deur).html&quot; title=&quot;Trappeur&quot;&gt;Trappeur&lt;/a&gt; (UM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Du-Cr&#233;puscule-(R&#244;deur).html&quot; title=&quot;Traqueur du cr&#233;puscule&quot;&gt;Traqueur du cr&#233;puscule&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Fetchelin-(Race).html&quot; title=&quot;Les fetchelins&quot;&gt;Fetchelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Sauvage-(R&#244;deur).html&quot; title=&quot;Traqueur sauvage&quot;&gt;Traqueur sauvage&lt;/a&gt; (UC)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Certains r&#244;deurs &#233;tudient leurs ennemis jur&#233;s et apprennent leurs coutumes afin d’am&#233;liorer leurs propres capacit&#233;s et d’utiliser les points forts de leurs ennemis contre eux. Les r&#244;deurs infiltr&#233;s peuvent se faire passer pour leurs ennemis pendant de tr&#232;s longues p&#233;riodes afin d’apprendre tout ce qu’il y a &#224; conna&#238;tre &#224; leur sujet et ainsi les chasser et les tuer plus efficacement.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Un r&#244;deur infiltr&#233; poss&#232;de les aptitudes de classe suivantes :&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Adaptation (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Adaptation_Ext_0&quot; href=&quot;#Adaptation_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;u&gt;Ce texte a &#233;t&#233; modifi&#233; suite &#224; la FAQ suivante :&lt;/u&gt;&lt;br /&gt;&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---R&#232;gles-Avanc&#233;es.html#45&quot; title=&quot;FAQ du Manuel des joueurs - R&#232;gles avanc&#233;es&quot;&gt;→&lt;/a&gt; R&#244;deur, R&#244;deur infiltr&#233; : Comment un r&#244;deur avec l&#39;arch&#233;type r&#244;deur infiltr&#233; (page 138), qui lui fait perdre sa capacit&#233; de classe environnement de pr&#233;dilection, peut-il utiliser les capacit&#233;s de classe camouflage et cach&#233; en pleine lumi&#232;re ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Un r&#244;deur avec l&#39;arch&#233;type &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Infiltr&#233;-(R&#244;deur).html&quot; title=&quot;R&#244;deur infiltr&#233;&quot;&gt;r&#244;deur infiltr&#233;&lt;/a&gt;&lt;/u&gt; peut utiliser les capacit&#233;s de classe &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#CAMOUFLAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;camouflage&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#CACHEENPLEINELUMIERE&quot; title=&quot;Le r&#244;deur&quot;&gt;cach&#233; en pleine lumi&#232;re&lt;/a&gt; chaque fois qu&#39;il utilise sa capacit&#233; de classe adaptation, qu&#39;importe le terrain o&#249; il se trouve.  
Mise &#224; jour : &#192; la page 138, dans l&#39;arch&#233;type r&#244;deur infiltr&#233;, dans la capacit&#233; de classe adaptation, ajoutez la phrase suivante &#224; la fin du second paragraphe :  
&#171; Le r&#244;deur peut utiliser les capacit&#233;s &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#CAMOUFLAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;camouflage&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#CACHEENPLEINELUMIERE&quot; title=&quot;Le r&#244;deur&quot;&gt;cach&#233; en pleine lumi&#232;re&lt;/a&gt; chaque fois qu&#39;il utilise des adaptations. &#187;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;Au niveau 3, un r&#244;deur infiltr&#233; apprend comment copier les capacit&#233;s sp&#233;ciales de sa proie. Il choisit un type de cr&#233;atures faisant partie de ses &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENNEMIJURE&quot; title=&quot;Le r&#244;deur&quot;&gt;ennemis jur&#233;s&lt;/a&gt; (comme par exemple les aberrations) et une capacit&#233; ou un don parmi la liste des adaptations possibles correspondant &#224; ce type (voir plus bas).&lt;br /&gt;&lt;br /&gt;Le r&#244;deur peut utiliser cette capacit&#233; chaque jour pendant 10 minutes par niveau de r&#244;deur. Il n’est pas oblig&#233; d’utiliser tout son quota quotidien en une seule fois mais chaque utilisation doit correspondre &#224; une dur&#233;e compl&#232;te de 10 minutes.&lt;br /&gt;&lt;br /&gt;Si l’adaptation n&#233;cessite que le r&#244;deur fasse un choix plus pr&#233;cis (comme par exemple la comp&#233;tence sur laquelle le don de Talent s’appliquera), ce choix est fait une fois pour toute et ne peut plus &#234;tre chang&#233; par la suite. &lt;br /&gt;&lt;br /&gt;Aux niveaux 8, 13 et 15, le r&#244;deur choisit un autre type parmi ses &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENNEMIJURE&quot; title=&quot;Le r&#244;deur&quot;&gt;ennemis jur&#233;s&lt;/a&gt; et une adaptation au sein de la liste correspondant &#224; ce type. Il choisit aussi une nouvelle adaptation dans une des listes correspondant aux types de cr&#233;atures qu’il a choisis dans le cadre de cette capacit&#233; (il peut s’agir du nouveau type qu’il vient de choisir). Le r&#244;deur infiltr&#233; ne peut utiliser qu’une seule adaptation &#224; la fois. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENVIRONNEMENTDEPREDILECTION&quot; title=&quot;Le r&#244;deur&quot;&gt;environnement de pr&#233;dilection&lt;/a&gt;. Le r&#244;deur peut utiliser les capacit&#233;s &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#CAMOUFLAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;camouflage&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#CACHEENPLEINELUMIERE&quot; title=&quot;Le r&#244;deur&quot;&gt;cach&#233; en pleine lumi&#232;re&lt;/a&gt; chaque fois qu’il utilise des adaptations.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Aberration&lt;/b&gt; : &lt;a class=&quot;pagelink&quot; href=&quot;Amphibie-(Capacit&#233;).html&quot; title=&quot;Amphibie&quot;&gt;amphibie&lt;/a&gt;, armure naturelle +2, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Animal&lt;/b&gt; : armure naturelle +2, escalade 4,50 m&#232;tres (3 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), nage 4,50 m&#232;tres (3 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vigueur-Surhumaine.html&quot; title=&quot;Vigueur surhumaine&quot;&gt;Vigueur surhumaine&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;vision nocturne&quot;&gt;vision nocturne&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cr&#233;ature artificielle&lt;/b&gt; : &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vigueur-Surhumaine.html&quot; title=&quot;Vigueur surhumaine&quot;&gt;Vigueur surhumaine&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;vision nocturne&quot;&gt;vision nocturne&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cr&#233;ature magique&lt;/b&gt; : armure naturelle +2, &lt;a class=&quot;pagelink&quot; href=&quot;Vigueur-Surhumaine.html&quot; title=&quot;Vigueur surhumaine&quot;&gt;Vigueur surhumaine&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;vision nocturne&quot;&gt;vision nocturne&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dragon&lt;/b&gt; : &lt;a class=&quot;pagelink&quot; href=&quot;Fente.html&quot; title=&quot;Fente&quot;&gt;Fente&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vigueur-Surhumaine.html&quot; title=&quot;Vigueur surhumaine&quot;&gt;Vigueur surhumaine&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;vision nocturne&quot;&gt;vision nocturne&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ext&#233;rieur&lt;/b&gt; : r&#233;sistance aux &#233;nergies 5 (choisir un type d’&#233;nergie parmi acide, feu, froid et &#233;lectricit&#233;), &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vigueur-Surhumaine.html&quot; title=&quot;Vigueur surhumaine&quot;&gt;Vigueur surhumaine&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;F&#233;e&lt;/b&gt; : &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;vision nocturne&quot;&gt;vision nocturne&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Humano&#239;de (aquatique)&lt;/b&gt; : armure naturelle +2, nage 4,50 m&#232;tres (3 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;vision nocturne&quot;&gt;vision nocturne&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Humano&#239;de (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;elfe&lt;/a&gt;)&lt;/b&gt; : armes famili&#232;res, immunit&#233;s elfiques, magie elfique, sang elfiqu